#ifndef SAVEDATA_H
#define SAVEDATA_H

#define     MAX_PLAYERS         4
#define     MAX_BTN_NUM         13

typedef struct
{
    unsigned compatibleversion;
    int gamma;
    int brightness;
    int usesound; // Use SB
    unsigned soundrate; // SB freq
    int soundvol; // SB volume
    int usemusic; // Play music
    int musicvol; // Music volume
    int effectvol; // Sound fx volume
    int soundbits; // SB bits
    int usejoy;
    int mode; // Mode now saves
    int windowpos;
    int keys[MAX_PLAYERS][MAX_BTN_NUM];
    int joyrumble[MAX_PLAYERS];
    int showtitles;
    int videoNTSC;
    int swfilter; // Software scaling filter
    int logo;
    int uselog;
    int debuginfo; // FPS, Memory, etc...
    int debug_collision_attack;
    int debug_collision_body;
    int debug_collision_range;
    int debug_position;
    int debug_features;
    int fullscreen; // Window or Full Screen Mode
    int stretch; // Stretch (1) or preserve aspect ratio (0) in fullscreen mode
    int screen[1][2];
#if SDL
    int usegl; // 1 if OpenGL is preferred over SDL software blitting
    float hwscale; // Scale factor for OpenGL
    int hwfilter; // Simple or bilinear scaling
#endif
#if PSP
    int pspcpuspeed; // PSP CPU Speed
    int overscan[4]; // Control TV Overscan
    int usetv; // Initilize TV at bootup
#endif
#if ANDROID
    int is_touchpad_vibration_enabled;
#endif
#if VITA
    int shader;
    int hwfilter;
#endif
	int vsync; // Sync to monitor refresh (1) or don't (0)
} s_savedata;

extern s_savedata     savedata;

#endif

functions.clearsettings:
void clearsettings()
{
    int i = 0;

    savedata.compatibleversion = COMPATIBLEVERSION;
    savedata.gamma = 0;
    savedata.brightness = 0;
    savedata.usesound = 1;
    savedata.soundrate = 44100;
    savedata.soundbits = 16;
    savedata.soundvol = 15;
    savedata.usemusic = 1;
    savedata.musicvol = 100;
    savedata.effectvol = 120;
    savedata.usejoy = 1;
    savedata.mode = 0;
    savedata.showtitles = 0;
    savedata.windowpos = 0;
    savedata.logo = 0;
    savedata.uselog = 1;
    savedata.debuginfo = 0;
    savedata.fullscreen = 0;
    #ifdef RASPBERRY
    savedata.fullscreen = 1;
    #endif
    savedata.vsync = 1;
    savedata.stretch = 0;

    savedata.swfilter = 0;

    #ifdef SDL
    savedata.usegl = 1;
    savedata.hwfilter = 1;
        #ifdef ANDROID
        savedata.hwscale = 0.0;
        #else
        savedata.hwscale = 1.0;
        #endif
    #endif

    #ifdef PSP
    savedata.pspcpuspeed = 2;
    savedata.overscan[0] = 0;
    savedata.overscan[1] = 0;
    savedata.overscan[2] = 0;
    savedata.overscan[3] = 0;
    #endif

    #ifdef ANDROID
    savedata.is_touchpad_vibration_enabled = 0;
    #endif

    for (i = 0; i < MAX_PLAYERS; i++)
    {
        clearbuttons(i);
    }
}

functions.savesettings:
void savesettings()
{
#ifndef DC
    FILE *handle = NULL;
    char path[MAX_BUFFER_LEN] = {""};
    char tmpname[MAX_BUFFER_LEN] = {""};
    getBasePath(path, "Saves", 0);
    getPakName(tmpname, 4);
    strcat(path, tmpname);
    handle = fopen(path, "wb");
    if(handle == NULL)
    {
        return;
    }
    fwrite(&savedata, 1, sizeof(savedata), handle);
    fclose(handle);
#endif
}

